'use client';

import { GripVertical, Plus, Trash2, X } from 'lucide-react';
import * as React from 'react';

import {
  ACTIVE_GROUP,
  FilterAddMenu,
  FilterConditionSelects,
  FilterValueInput,
  groupTargetProps,
  type TFilterEditorProps,
  type TFilterScope,
} from '@/components/ui-fragments/filter-builder/filter-parts';
import {
  createFilterGroup,
  withFilterValue,
  type TFilterGroup,
  type TFilterJoin,
  type TFilterNode,
} from '@/components/ui-fragments/filter-builder/filter-query';
import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/default/ui/select';
import {
  Sortable,
  SortableContent,
  SortableItem,
  SortableItemHandle,
} from '@/registry/default/ui/sortable';

// A filter is a tree: a group joins its children with one `$and` or one
// `$or`, and a child is a condition or another group. The builder draws each
// group as rows, the way the data table's flat filters are drawn ("Where",
// then the join, then the join again), and a nested group as a framed block in
// its parent's row. It fits a popover; the `FilterBar` draws the same tree
// inline. The pure model lives in `filter-query.ts`.

function FilterBuilder({
  fields,
  unavailableFields,
  value,
  onChange,
  maxDepth = 2,
  suggestions,
  activeGroupId,
  onActiveGroupChange,
  className,
}: TFilterEditorProps) {
  const scope = {
    fields,
    unavailableFields,
    depth: 1,
    maxDepth,
    suggestions,
    activeGroupId,
    onActiveGroupChange,
  };

  return (
    <div
      data-slot="filter-builder"
      {...groupTargetProps(value.id, scope)}
      className={cn(
        'flex flex-col gap-3',
        // With a target to mark, the root is a group frame like the others.
        onActiveGroupChange && [
          'rounded-md border border-dashed p-2',
          ACTIVE_GROUP,
        ],
        className
      )}
    >
      <FilterGroupBody
        group={value}
        onChange={onChange}
        scope={scope}
        footer={
          value.children.length > 0 && (
            <Button
              type="button"
              variant="ghost"
              className="gap-2"
              onClick={() => onChange(createFilterGroup(value.join))}
            >
              Reset
              <X className="size-4" />
            </Button>
          )
        }
      />
    </div>
  );
}

function FilterGroupBody({
  group,
  onChange,
  scope,
  footer,
}: {
  group: TFilterGroup;
  onChange: (group: TFilterGroup) => void;
  scope: TFilterScope;
  footer?: React.ReactNode;
}) {
  const setChildren = (children: readonly TFilterNode[]) =>
    onChange({ ...group, children });
  const isRoot = scope.depth === 1;
  const canNest = scope.depth < scope.maxDepth;
  // An empty root is the first thing a popover shows: centered, as the data
  // table's filters always were, with Add filter under the text.
  const isEmptyRoot = isRoot && group.children.length === 0;

  return (
    <div className={cn('flex flex-col gap-2', isEmptyRoot && 'gap-4 py-2')}>
      {isEmptyRoot ? (
        <div className="flex flex-col gap-1 text-center">
          <p className="text-sm font-medium">No filters applied</p>
          <p className="text-muted-foreground text-sm">
            Add filters to refine the rows.
          </p>
        </div>
      ) : group.children.length === 0 ? (
        <p className="text-muted-foreground px-1 text-sm">
          An empty group filters nothing.
        </p>
      ) : (
        <Sortable
          value={[...group.children]}
          getItemValue={(node: TFilterNode) => node.id}
          onValueChange={setChildren}
        >
          <SortableContent className="flex flex-col gap-2">
            {group.children.map((node, index) => (
              <FilterRow
                key={node.id}
                node={node}
                index={index}
                join={group.join}
                scope={scope}
                onJoinChange={(join) => onChange({ ...group, join })}
                onChange={(next) =>
                  setChildren(
                    group.children.map((one) =>
                      one.id === next.id ? next : one
                    )
                  )
                }
                onRemove={() =>
                  setChildren(group.children.filter((one) => one !== node))
                }
              />
            ))}
          </SortableContent>
        </Sortable>
      )}
      <div
        className={cn(
          'flex flex-wrap items-center gap-2',
          isEmptyRoot && 'justify-center'
        )}
      >
        <FilterAddMenu
          fields={scope.fields}
          unavailable={scope.unavailableFields}
          canNest={canNest}
          join={group.join}
          onAdd={(node) => setChildren([...group.children, node])}
        >
          <Button
            type="button"
            variant={isRoot ? 'primary' : 'outline'}
            className="gap-2"
          >
            <Plus className="size-4" />
            Add filter
          </Button>
        </FilterAddMenu>
        {footer}
      </div>
    </div>
  );
}

function FilterRow({
  node,
  index,
  join,
  scope,
  onJoinChange,
  onChange,
  onRemove,
}: {
  node: TFilterNode;
  index: number;
  join: TFilterJoin;
  scope: TFilterScope;
  onJoinChange: (join: TFilterJoin) => void;
  onChange: (node: TFilterNode) => void;
  onRemove: () => void;
}) {
  if (node.kind === 'group') {
    // A group's remove and drag controls sit in its own footer, not in a
    // column beside the frame, so a nested row keeps that width for values.
    return (
      <SortableItem value={node.id} className="flex items-start gap-2">
        <FilterJoinCell index={index} join={join} onChange={onJoinChange} />
        <div
          data-slot="filter-group"
          {...groupTargetProps(node.id, scope)}
          className={cn(
            'bg-muted/40 min-w-0 flex-1 rounded-md border border-dashed p-2',
            ACTIVE_GROUP
          )}
        >
          <FilterGroupBody
            group={node}
            onChange={onChange}
            scope={{ ...scope, depth: scope.depth + 1 }}
            footer={
              <div className="ml-auto flex gap-2">
                <FilterRowActions label="Remove group" onRemove={onRemove} />
              </div>
            }
          />
        </div>
      </SortableItem>
    );
  }

  return (
    <SortableItem value={node.id} className="flex items-start gap-2">
      <FilterJoinCell index={index} join={join} onChange={onJoinChange} />
      <div
        data-slot="filter-condition"
        className="flex min-w-0 flex-1 items-start gap-2"
      >
        <FilterConditionSelects
          condition={node}
          fields={scope.fields}
          onChange={onChange}
          fieldClassName="w-40 shrink-0"
          operatorClassName="w-32 shrink-0"
        />
        <FilterValueInput
          condition={node}
          fields={scope.fields}
          suggestions={scope.suggestions}
          onChange={(value) =>
            onChange(withFilterValue(node, value, scope.fields))
          }
          className="min-w-0 flex-1"
        />
      </div>
      <FilterRowActions label="Remove filter" onRemove={onRemove} />
    </SortableItem>
  );
}

/** Remove, then the drag handle. Rendered inside its row's `SortableItem`. */
function FilterRowActions({
  label,
  onRemove,
}: {
  label: string;
  onRemove: () => void;
}) {
  return (
    <>
      <Button
        type="button"
        variant="outline"
        size="icon-md"
        className="shrink-0"
        onClick={onRemove}
      >
        <Trash2 />
        <span className="sr-only">{label}</span>
      </Button>
      <SortableItemHandle asChild>
        <Button
          type="button"
          variant="outline"
          size="icon-md"
          className="shrink-0"
        >
          <GripVertical className="text-muted-foreground" />
          <span className="sr-only">Drag to reorder</span>
        </Button>
      </SortableItemHandle>
    </>
  );
}

/**
 * The cell before a row: "Where" on the first, the group's join as a choice
 * on the second, and the same join as text after it. One group has one join,
 * so it is chosen once.
 */
function FilterJoinCell({
  index,
  join,
  onChange,
}: {
  index: number;
  join: TFilterJoin;
  onChange: (join: TFilterJoin) => void;
}) {
  if (index !== 1) {
    return (
      <span className="text-muted-foreground flex h-8 w-18 shrink-0 items-center px-2 text-sm">
        {index === 0 ? 'Where' : join}
      </span>
    );
  }

  return (
    <Select
      value={join}
      onValueChange={(next) => onChange(next === 'or' ? 'or' : 'and')}
    >
      <SelectTrigger aria-label="Join" className="w-18 shrink-0">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="and">and</SelectItem>
        <SelectItem value="or">or</SelectItem>
      </SelectContent>
    </Select>
  );
}

export { FilterBuilder };

'use client';

import { ArrowLeftRight, GripVertical, Plus, Trash2, X } from 'lucide-react';
import * as React from 'react';

import {
  ACTIVE_GROUP,
  FilterAddMenu,
  FilterConditionSelects,
  FilterValueInput,
  groupTargetProps,
  type TFilterEditorProps,
  type TFilterScope,
} from '@/components/ui-fragments/filter-builder/filter-parts';
import {
  createFilterGroup,
  withFilterValue,
  type TFilterCondition,
  type TFilterGroup,
  type TFilterJoin,
  type TFilterNode,
} from '@/components/ui-fragments/filter-builder/filter-query';
import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import {
  Sortable,
  SortableContent,
  SortableItem,
  SortableItemHandle,
} from '@/registry/default/ui/sortable';

// The filter, always on screen above a table: the same tree as the
// `FilterBuilder`, drawn inline. A condition is one chip of segments (field,
// operator, value, remove); a group is a framed run of chips; between two
// children of a group sits its join, an outlined pill with a swap icon, and a
// click on it switches the whole group between `and` and `or`. A group left
// empty is removed with it.

type TFilterBarProps = TFilterEditorProps & {
  /** The toolbar's other controls, after Reset in the same row: Inspect query. */
  actions?: React.ReactNode;
};

/** A control drawn as one segment of a chip: no frame of its own. */
const CHIP_SEGMENT =
  'h-full w-auto rounded-none border-0 bg-transparent px-2 shadow-none focus:ring-0 focus:ring-offset-0 focus-visible:ring-0 dark:bg-transparent dark:hover:bg-muted/50 hover:bg-muted';

function FilterBar({
  fields,
  unavailableFields,
  value,
  onChange,
  maxDepth = 2,
  suggestions,
  activeGroupId,
  onActiveGroupChange,
  actions,
  className,
}: TFilterBarProps) {
  const scope = {
    fields,
    unavailableFields,
    depth: 1,
    maxDepth,
    suggestions,
    activeGroupId,
    onActiveGroupChange,
  };
  const add = (node: TFilterNode) =>
    onChange({ ...value, children: [...value.children, node] });

  return (
    <div
      data-slot="filter-bar"
      {...groupTargetProps(value.id, scope)}
      className={cn(
        'flex flex-wrap items-center gap-1.5',
        // With a target to mark, the root is a group frame like the others.
        onActiveGroupChange && [
          'rounded-md border border-dashed p-1',
          ACTIVE_GROUP,
        ],
        className
      )}
    >
      <FilterBarNodes group={value} onChange={onChange} scope={scope} />
      <FilterAddMenu
        fields={fields}
        unavailable={unavailableFields}
        canNest={maxDepth > 1}
        join={value.join}
        onAdd={add}
      >
        <Button type="button" variant="outlineDashed" className="gap-2">
          <Plus className="size-4" />
          Add filter
        </Button>
      </FilterAddMenu>
      {value.children.length > 0 && (
        <Button
          type="button"
          variant="ghost"
          className="gap-2"
          onClick={() => onChange(createFilterGroup(value.join))}
        >
          Reset
          <X className="size-4" />
        </Button>
      )}
      {actions}
    </div>
  );
}

/**
 * A group's children, with its join between each two. They are drawn straight
 * into the parent's row (`withoutSlot`), so the row wraps them, and a group is
 * dragged by its handle to another place among its siblings.
 */
function FilterBarNodes({
  group,
  onChange,
  scope,
}: {
  group: TFilterGroup;
  onChange: (group: TFilterGroup) => void;
  scope: TFilterScope;
}) {
  const otherJoin: TFilterJoin = group.join === 'and' ? 'or' : 'and';

  return (
    <Sortable
      value={[...group.children]}
      getItemValue={(node: TFilterNode) => node.id}
      onValueChange={(children) => onChange({ ...group, children })}
      orientation="mixed"
    >
      <SortableContent withoutSlot>
        {group.children.map((node, index) => {
          const replace = (next: TFilterNode | null) =>
            onChange({
              ...group,
              children:
                next === null ||
                (next.kind === 'group' && next.children.length === 0)
                  ? group.children.filter((one) => one !== node)
                  : group.children.map((one) => (one === node ? next : one)),
            });

          return (
            <React.Fragment key={node.id}>
              {index > 0 && (
                <Button
                  type="button"
                  variant="outline"
                  caseSensitive
                  title={`Switch this group to ${otherJoin}`}
                  className="text-muted-foreground hover:text-foreground h-6 gap-1 rounded-full px-2 text-xs"
                  onClick={() => onChange({ ...group, join: otherJoin })}
                >
                  {group.join}
                  <ArrowLeftRight className="size-3" />
                </Button>
              )}
              <SortableItem value={node.id} className="inline-flex max-w-full">
                {node.kind === 'condition' ? (
                  <FilterChip
                    condition={node}
                    scope={scope}
                    onChange={replace}
                    onRemove={() => replace(null)}
                  />
                ) : (
                  <FilterGroupFrame
                    group={node}
                    scope={scope}
                    onChange={replace}
                  />
                )}
              </SortableItem>
            </React.Fragment>
          );
        })}
      </SortableContent>
    </Sortable>
  );
}

/** A nested group: its handle, its chips, then add and remove. */
function FilterGroupFrame({
  group,
  scope,
  onChange,
}: {
  group: TFilterGroup;
  scope: TFilterScope;
  /** `null` removes the group. */
  onChange: (group: TFilterGroup | null) => void;
}) {
  return (
    <div
      data-slot="filter-group"
      {...groupTargetProps(group.id, scope)}
      className={cn(
        'bg-muted/40 inline-flex flex-wrap items-center gap-1.5 rounded-md border border-dashed p-1',
        ACTIVE_GROUP
      )}
    >
      <SortableItemHandle asChild>
        <Button type="button" variant="outline" size="icon-md">
          <GripVertical className="text-muted-foreground" />
          <span className="sr-only">Drag to reorder</span>
        </Button>
      </SortableItemHandle>
      <FilterBarNodes
        group={group}
        onChange={onChange}
        scope={{ ...scope, depth: scope.depth + 1 }}
      />
      <span className="inline-flex gap-1.5">
        <FilterAddMenu
          fields={scope.fields}
          unavailable={scope.unavailableFields}
          canNest={scope.depth + 1 < scope.maxDepth}
          join={group.join}
          onAdd={(child) =>
            onChange({ ...group, children: [...group.children, child] })
          }
        >
          <Button type="button" variant="outline" size="icon-md">
            <Plus />
            <span className="sr-only">Add to group</span>
          </Button>
        </FilterAddMenu>
        <Button
          type="button"
          variant="outline"
          size="icon-md"
          onClick={() => onChange(null)}
        >
          <Trash2 />
          <span className="sr-only">Remove group</span>
        </Button>
      </span>
    </div>
  );
}

function FilterChip({
  condition,
  scope,
  onChange,
  onRemove,
}: {
  condition: TFilterCondition;
  scope: TFilterScope;
  onChange: (condition: TFilterCondition) => void;
  onRemove: () => void;
}) {
  return (
    <div
      data-slot="filter-chip"
      // The dividers are drawn by the chip, not by `divide-x`: its rule has no
      // specificity, so the segments' `border-0` erased it.
      className="bg-background inline-flex h-8 max-w-full items-stretch overflow-hidden rounded-md border text-sm [&>*:not(:last-child)]:border-r"
    >
      <FilterConditionSelects
        condition={condition}
        fields={scope.fields}
        onChange={onChange}
        fieldClassName={cn(CHIP_SEGMENT, 'gap-1')}
        operatorClassName={cn(CHIP_SEGMENT, 'gap-1')}
      />
      <FilterValueInput
        condition={condition}
        fields={scope.fields}
        suggestions={scope.suggestions}
        onChange={(value) =>
          onChange(withFilterValue(condition, value, scope.fields))
        }
        className={cn(CHIP_SEGMENT, 'field-sizing-content max-w-56 min-w-12')}
      />
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        className={CHIP_SEGMENT}
        onClick={onRemove}
      >
        <X />
        <span className="sr-only">Remove filter</span>
      </Button>
    </div>
  );
}

export { FilterBar, type TFilterBarProps };

'use client';

import { CalendarIcon, Check, ChevronsUpDown, ListPlus } from 'lucide-react';
import * as React from 'react';
import type { DateRange } from 'react-day-picker';

import {
  createFilterCondition,
  createFilterSubgroup,
  filterConditionLabel,
  filterConditionOperators,
  filterKeyType,
  filterValueFor,
  withFilterValue,
  type TFilterCondition,
  type TFilterFields,
  type TFilterGroup,
  type TFilterJoin,
  type TFilterNode,
  type TFilterOperator,
  type TFilterValue,
} from '@/components/ui-fragments/filter-builder/filter-query';
import { cn } from '@/lib/utils';
import { Button } from '@/registry/default/ui/button';
import { Calendar } from '@/registry/default/ui/calendar';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/registry/default/ui/command';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/default/ui/dropdown-menu';
import { Input } from '@/registry/default/ui/input';
import {
  Popover,
  PopoverAnchor,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/default/ui/popover';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/registry/default/ui/select';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/registry/default/ui/tooltip';

// The parts both layouts draw a condition with: the `FilterBuilder` as rows,
// the `FilterBar` as chips. Each layout gives them its own class names.

/**
 * What the reader is typing in one input of a condition, given to a consumer
 * that offers values for it.
 */
type TFilterSuggestionRequest = {
  condition: TFilterCondition;
  /** The input: a keyed value's key, or the value. */
  part: 'key' | 'value';
  /** What the input holds now. */
  text: string;
  /** Writes a text into that input and closes the offers. */
  pick: (text: string) => void;
};

/** One value an input offers: what it writes, how it reads, how many hold it. */
type TFilterSuggestion = { value: string; label?: string; count?: number };

/** A field the reader cannot add now, and why. */
type TFilterUnavailableField = { label: string; reason: string };

type TFilterEditorProps = {
  /** The resource's vocabulary: its fields, by field id. */
  fields: TFilterFields;
  /** The root group. Start from `createFilterGroup()` or `filterOfQuery()`. */
  value: TFilterGroup;
  onChange: (value: TFilterGroup) => void;
  /**
   * The fields of the vocabulary the reader cannot add now, by field id. Add
   * filter lists them after the others, disabled, with the reason on hover.
   */
  unavailableFields?: Readonly<Record<string, TFilterUnavailableField>>;
  /**
   * How many levels of groups the reader can open. `1` is a flat list with
   * one join, as the data table's filters are today; `2` holds an `$or` of
   * `$and`s.
   */
  maxDepth?: number;
  /**
   * What a value or key input offers while it has focus, drawn under it:
   * usually a `FilterSuggestionList`. It is mounted only while the input has
   * focus, so what it reads is read only then. `null` offers nothing.
   */
  suggestions?: (request: TFilterSuggestionRequest) => React.ReactNode;
  /**
   * The group marked as the target, for a surface that writes into one group
   * of the tree (a filter panel). The root is a group too.
   */
  activeGroupId?: string;
  /** A press inside a group makes it the target: the innermost group. */
  onActiveGroupChange?: (groupId: string) => void;
  className?: string;
};

/** Where a group sits in the tree, given to each level as it is drawn. */
type TFilterScope = Pick<
  TFilterEditorProps,
  'suggestions' | 'activeGroupId' | 'onActiveGroupChange' | 'unavailableFields'
> & {
  fields: TFilterFields;
  depth: number;
  maxDepth: number;
};

const DAY_OPTIONS: Intl.DateTimeFormatOptions = {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
};

/** The days in the reader's time zone: in the browser only. */
const DAY_FORMAT = new Intl.DateTimeFormat('en-US', DAY_OPTIONS);

/**
 * The days on the server and in the hydration pass, which must draw the same
 * text and know no reader's time zone.
 */
const UTC_DAY_FORMAT = new Intl.DateTimeFormat('en-US', {
  ...DAY_OPTIONS,
  timeZone: 'UTC',
});

const subscribeToNothing = () => () => {};

const COUNT_FORMAT = new Intl.NumberFormat('en-US');

/** Presses a group already took: the innermost group a press reaches. */
const TARGETED_PRESSES = new WeakSet<Event>();

/**
 * What makes a group the target of a press inside it, when the surface asks
 * for a target. A press bubbles from the innermost group out, through React
 * portals too (a select opened from a chip), so the first group it reaches
 * takes it and the groups around it let it pass.
 */
function groupTargetProps(
  groupId: string,
  scope: TFilterScope
): React.HTMLAttributes<HTMLDivElement> & { 'data-active'?: boolean } {
  const { onActiveGroupChange } = scope;

  if (!onActiveGroupChange) {
    return {};
  }

  return {
    'data-active': scope.activeGroupId === groupId,
    onPointerDown: (event) => {
      if (TARGETED_PRESSES.has(event.nativeEvent)) {
        return;
      }

      TARGETED_PRESSES.add(event.nativeEvent);
      onActiveGroupChange(groupId);
    },
  };
}

/**
 * The frame of the target group: solid, in the foreground at low opacity, as a
 * checked card's. Not `border-primary`: the dark theme's primary is its border
 * color, so the mark was gone there, and in the light theme it was too heavy.
 */
const ACTIVE_GROUP =
  'data-[active=true]:border-solid data-[active=true]:border-foreground/30';

/**
 * **The one way to add to a group**, in both layouts: the trigger (Add filter)
 * opens the fields, and a condition starts on the field picked. A field the
 * reader cannot add follows them, disabled, with its reason on hover. When
 * `canNest`, **Group** is the last item: a group of the other join with one
 * condition in it. A group is one more thing to add, not a second button.
 */
function FilterAddMenu({
  fields,
  unavailable = {},
  canNest,
  join,
  onAdd,
  children,
}: {
  fields: TFilterFields;
  unavailable?: TFilterEditorProps['unavailableFields'];
  canNest: boolean;
  /** The join of the group added to. A new group takes the other one. */
  join: TFilterJoin;
  onAdd: (node: TFilterNode) => void;
  /** The trigger. */
  children: React.ReactNode;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>{children}</DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-48">
        {Object.entries(fields).map(([key, field]) => (
          <DropdownMenuItem
            key={key}
            onSelect={() => onAdd(createFilterCondition(fields, key))}
          >
            {field.label}
          </DropdownMenuItem>
        ))}
        {Object.entries(unavailable)
          // A field already in the vocabulary is offered above.
          .filter(([key]) => !(key in fields))
          .map(([key, { label, reason }]) => (
            <Tooltip key={key}>
              {/* A disabled item takes no pointer events: the span holds the hover. */}
              <TooltipTrigger asChild>
                <span className="block">
                  <DropdownMenuItem disabled data-field={key}>
                    {label}
                  </DropdownMenuItem>
                </span>
              </TooltipTrigger>
              <TooltipContent side="right" className="max-w-64">
                {reason}
              </TooltipContent>
            </Tooltip>
          ))}
        {canNest && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              onSelect={() => onAdd(createFilterSubgroup(fields, join))}
            >
              <ListPlus />
              Group
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * The field: a searchable list. A field list can be long, so the reader types
 * to find one. A new field starts a new condition.
 */
function FilterFieldPicker({
  condition,
  fields,
  onChange,
  className,
}: {
  condition: TFilterCondition;
  fields: TFilterFields;
  onChange: (condition: TFilterCondition) => void;
  className?: string;
}) {
  const [open, setOpen] = React.useState(false);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          role="combobox"
          aria-label="Field"
          aria-expanded={open}
          className={cn('justify-between gap-2 px-3 font-normal', className)}
        >
          <span className="truncate">
            {filterConditionLabel(condition, fields) ?? 'Select field'}
          </span>
          <ChevronsUpDown className="size-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="p-0">
        {/* The keyboard starts on the current field. */}
        <Command defaultValue={fields[condition.field]?.label}>
          <CommandInput placeholder="Search fields..." />
          <CommandList>
            <CommandEmpty>No fields found.</CommandEmpty>
            <CommandGroup>
              {Object.entries(fields).map(([key, one]) => (
                <CommandItem
                  key={key}
                  // The search reads the label the reader sees, and the id.
                  value={one.label}
                  keywords={[key]}
                  onSelect={() => {
                    if (key !== condition.field) {
                      onChange({
                        ...createFilterCondition(fields, key),
                        id: condition.id,
                      });
                    }
                    setOpen(false);
                  }}
                >
                  <span className="truncate">{one.label}</span>
                  <Check
                    className={cn(
                      'ml-auto',
                      key === condition.field ? 'opacity-100' : 'opacity-0'
                    )}
                  />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

/** The field, then the operator. */
function FilterConditionSelects({
  condition,
  fields,
  onChange,
  fieldClassName,
  operatorClassName,
}: {
  condition: TFilterCondition;
  fields: TFilterFields;
  onChange: (condition: TFilterCondition) => void;
  fieldClassName?: string;
  operatorClassName?: string;
}) {
  const field = fields[condition.field];
  const operators = filterConditionOperators(condition, fields);

  return (
    <>
      <FilterFieldPicker
        condition={condition}
        fields={fields}
        onChange={onChange}
        className={fieldClassName}
      />
      <Select
        value={condition.operator}
        onValueChange={(next) => {
          const operator = operators.find((one) => one.value === next)?.value;

          if (operator) {
            onChange(
              withFilterValue(
                { ...condition, operator },
                filterValueFor(field, operator, condition.value),
                fields
              )
            );
          }
        }}
      >
        <SelectTrigger
          aria-label="Operator"
          className={cn('lowercase', operatorClassName)}
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {operators.map((one) => (
            <SelectItem key={one.value} value={one.value} className="lowercase">
              {one.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </>
  );
}

type TFilterValueInputProps = {
  condition: TFilterCondition;
  fields: TFilterFields;
  onChange: (value: TFilterValue) => void;
  suggestions?: TFilterEditorProps['suggestions'];
  /** Given to each control the value takes: one, or two for a keyed value. */
  className?: string;
};

const takesValue = (condition: TFilterCondition) =>
  condition.operator !== 'isEmpty' && condition.operator !== 'isNotEmpty';

function FilterValueInput(props: TFilterValueInputProps) {
  const { value } = props.condition;

  switch (value.kind) {
    case 'instants':
      return (
        <FilterRangeInput
          value={value}
          onChange={props.onChange}
          className={props.className}
        />
      );
    case 'keyed':
      return <FilterKeyedInput {...props} value={value} />;
    case 'list':
      return <FilterListInput {...props} value={value} />;
    case 'text':
      return takesValue(props.condition) ? (
        <FilterTextInput {...props} value={value} />
      ) : null;
  }
}

/**
 * A key, then its value unless the operator takes none. A field fixed on one
 * key (a key that the field list names) asks no key: its label names it. On
 * the metadata field with no key, only a new condition asks one: a key read
 * from a query is in the label (`Metadata · <key>`).
 *
 * A key whose type the consumer knows takes its value in that type: `true` or
 * `false`, a number, or a day.
 */
function FilterKeyedInput({
  condition,
  fields,
  onChange,
  suggestions,
  className,
  value,
}: TFilterValueInputProps & {
  value: Extract<TFilterValue, { kind: 'keyed' }>;
}) {
  const field = fields[condition.field];
  const asksKey =
    field?.key === undefined &&
    (field?.variant !== 'metadata' ||
      value.asksKey === true ||
      value.key.trim() === '');
  const format = filterKeyType(field, value.key)?.format ?? 'string';
  const onText = (text: string) => onChange({ ...value, text });

  return (
    <>
      {asksKey && (
        <SuggestedInput
          aria-label="Key"
          className={className}
          placeholder={field?.placeholderKey ?? 'Key...'}
          text={value.key}
          onText={(key) => onChange({ ...value, key })}
          offers={
            suggestions &&
            ((text, pick) =>
              suggestions({ condition, part: 'key', text, pick }))
          }
        />
      )}
      {takesValue(condition) &&
        (format === 'bool' ? (
          <Select value={value.text} onValueChange={onText}>
            <SelectTrigger aria-label="Value" className={className}>
              <SelectValue placeholder="Pick a value" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="true">true</SelectItem>
              <SelectItem value="false">false</SelectItem>
            </SelectContent>
          </Select>
        ) : format === 'unixMicros' ? (
          <FilterDayInput
            micros={value.text}
            operator={condition.operator}
            onMicros={onText}
            className={className}
          />
        ) : (
          <SuggestedInput
            aria-label="Value"
            className={className}
            inputMode={format === 'string' ? undefined : 'numeric'}
            placeholder={
              format === 'string'
                ? (field?.placeholderValue ?? 'Value...')
                : 'Number...'
            }
            text={value.text}
            onText={onText}
            offers={
              suggestions &&
              ((text, pick) =>
                suggestions({ condition, part: 'value', text, pick }))
            }
          />
        ))}
    </>
  );
}

/**
 * Items are kept as typed, blanks included, so a trailing comma stays in the
 * box; the query drops the blanks.
 */
function FilterListInput({
  condition,
  fields,
  onChange,
  className,
  value,
}: TFilterValueInputProps & {
  value: Extract<TFilterValue, { kind: 'list' }>;
}) {
  return (
    <Input
      aria-label="Values"
      className={className}
      placeholder={fields[condition.field]?.placeholder ?? 'One, two, three...'}
      value={value.items.join(',')}
      onChange={(event) =>
        onChange({ kind: 'list', items: event.target.value.split(',') })
      }
    />
  );
}

/** A choice when the field has options (a boolean has two), else a text box. */
function FilterTextInput({
  condition,
  fields,
  onChange,
  suggestions,
  className,
  value,
}: TFilterValueInputProps & {
  value: Extract<TFilterValue, { kind: 'text' }>;
}) {
  const field = fields[condition.field];
  const options =
    field?.variant === 'boolean'
      ? [
          { label: 'True', value: 'true' },
          { label: 'False', value: 'false' },
        ]
      : field?.options;

  return options ? (
    <Select
      value={value.text}
      onValueChange={(text) => onChange({ kind: 'text', text })}
    >
      <SelectTrigger aria-label="Value" className={className}>
        <SelectValue placeholder={field?.placeholder ?? 'Pick a value'} />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  ) : (
    <SuggestedInput
      aria-label="Value"
      className={className}
      inputMode={field?.variant === 'number' ? 'numeric' : undefined}
      placeholder={field?.placeholder ?? 'Value...'}
      text={value.text}
      onText={(text) => onChange({ kind: 'text', text })}
      offers={
        suggestions &&
        ((text, pick) => suggestions({ condition, part: 'value', text, pick }))
      }
    />
  );
}

/**
 * An input that offers values under it while it has focus. The offers are
 * mounted only while it is open. ArrowDown moves into them, and a pick writes
 * the value and gives the focus back to the input.
 */
function SuggestedInput({
  text,
  onText,
  offers,
  ...props
}: Omit<React.ComponentProps<typeof Input>, 'value' | 'onChange'> & {
  text: string;
  onText: (text: string) => void;
  offers?: (text: string, pick: (text: string) => void) => React.ReactNode;
}) {
  const [isOpen, setIsOpen] = React.useState(false);
  const generatedId = React.useId();
  const inputId = props.id ?? generatedId;
  const contentRef = React.useRef<HTMLDivElement | null>(null);

  if (!offers) {
    return (
      <Input
        {...props}
        value={text}
        onChange={(event) => onText(event.target.value)}
      />
    );
  }

  const pick = (picked: string) => {
    onText(picked);
    document.getElementById(inputId)?.focus();
    setIsOpen(false);
  };
  const isInside = (target: EventTarget | null) =>
    target instanceof HTMLElement &&
    (target.id === inputId || contentRef.current?.contains(target));

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverAnchor asChild>
        <Input
          {...props}
          id={inputId}
          autoComplete="off"
          value={text}
          onChange={(event) => {
            onText(event.target.value);
            setIsOpen(true);
          }}
          onFocus={() => setIsOpen(true)}
          onBlur={(event) => {
            if (!isInside(event.relatedTarget)) {
              setIsOpen(false);
            }
          }}
          onKeyDown={(event) => {
            if (event.key === 'ArrowDown') {
              event.preventDefault();
              setIsOpen(true);
              contentRef.current
                ?.querySelector<HTMLElement>('[data-slot=filter-suggestion]')
                ?.focus();
            }
          }}
        />
      </PopoverAnchor>
      <PopoverContent
        ref={contentRef}
        align="start"
        className="w-64 p-1 empty:hidden"
        // The input keeps the focus: the offers follow what is typed.
        onOpenAutoFocus={(event) => event.preventDefault()}
        onCloseAutoFocus={(event) => event.preventDefault()}
        onInteractOutside={(event) => {
          if (isInside(event.target)) {
            event.preventDefault();
          }
        }}
        onBlur={(event) => {
          if (!isInside(event.relatedTarget)) {
            setIsOpen(false);
          }
        }}
      >
        {isOpen && offers(text, pick)}
      </PopoverContent>
    </Popover>
  );
}

/**
 * The values an input offers, each with how many rows hold it when that is
 * known. Draws nothing when there is nothing to offer. ArrowUp and ArrowDown
 * move between the values.
 */
function FilterSuggestionList({
  items,
  onPick,
}: {
  items: readonly TFilterSuggestion[];
  onPick: (value: string) => void;
}) {
  if (items.length === 0) {
    return null;
  }

  const move = (event: React.KeyboardEvent<HTMLElement>, step: 1 | -1) => {
    const all = [
      ...(event.currentTarget.parentElement?.querySelectorAll<HTMLElement>(
        '[data-slot=filter-suggestion]'
      ) ?? []),
    ];
    const next = all[all.indexOf(event.target as HTMLElement) + step];

    if (next) {
      event.preventDefault();
      next.focus();
    }
  };

  return (
    <div
      role="listbox"
      aria-label="Suggestions"
      className="flex max-h-64 flex-col overflow-y-auto"
      onKeyDown={(event) => {
        if (event.key === 'ArrowDown') {
          move(event, 1);
        }

        if (event.key === 'ArrowUp') {
          move(event, -1);
        }
      }}
    >
      {items.map((item) => (
        <Button
          key={item.value}
          type="button"
          role="option"
          aria-selected={false}
          variant="ghost"
          caseSensitive
          data-slot="filter-suggestion"
          className="w-full shrink-0 justify-between gap-3 font-sans font-normal"
          // A press must not take the focus from the input before the click.
          onMouseDown={(event) => event.preventDefault()}
          onClick={() => onPick(item.value)}
        >
          <span className="truncate">{item.label ?? item.value}</span>
          {item.count !== undefined && (
            <span className="text-muted-foreground font-mono text-xs tabular-nums">
              {COUNT_FORMAT.format(item.count)}
            </span>
          )}
        </Button>
      ))}
    </div>
  );
}

/**
 * A range of whole days. The first day counts from its start and the last to
 * its end, so a one-day pick holds that whole day.
 */
function FilterRangeInput({
  value,
  onChange,
  className,
}: {
  value: Extract<TFilterValue, { kind: 'instants' }>;
  onChange: (value: TFilterValue) => void;
  className?: string;
}) {
  const selected: DateRange | undefined =
    value.from && value.to
      ? { from: new Date(value.from), to: new Date(value.to) }
      : undefined;
  const days = React.useSyncExternalStore(
    subscribeToNothing,
    () => DAY_FORMAT,
    () => UTC_DAY_FORMAT
  );

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          caseSensitive
          className={cn(
            'justify-start gap-2 font-sans font-normal',
            !selected && 'text-muted-foreground',
            className
          )}
        >
          <CalendarIcon className="size-4 shrink-0" />
          <span className="truncate">
            {selected?.from && selected.to
              ? `${days.format(selected.from)} – ${days.format(selected.to)}`
              : 'Pick a range of days'}
          </span>
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-0">
        <Calendar
          mode="range"
          numberOfMonths={2}
          selected={selected}
          onSelect={(range) => {
            if (!range?.from) {
              onChange({ kind: 'instants', from: '', to: '' });

              return;
            }

            const from = new Date(range.from);
            const to = new Date(range.to ?? range.from);
            from.setHours(0, 0, 0, 0);
            to.setHours(23, 59, 59, 999);
            onChange({
              kind: 'instants',
              from: from.toISOString(),
              to: to.toISOString(),
            });
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

/**
 * One day, written as signed Unix microseconds (a `datetime` metadata key). A
 * bound that holds the day (`≥`, `≤`) or leaves it out (`<`, `>`) takes the
 * start or the end of the day, so a day picked is a whole day.
 */
function FilterDayInput({
  micros,
  operator,
  onMicros,
  className,
}: {
  micros: string;
  operator: TFilterOperator;
  onMicros: (micros: string) => void;
  className?: string;
}) {
  const selected = /^-?\d+$/.test(micros.trim())
    ? new Date(Math.floor(Number(micros) / 1000))
    : undefined;
  const days = React.useSyncExternalStore(
    subscribeToNothing,
    () => DAY_FORMAT,
    () => UTC_DAY_FORMAT
  );

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="outline"
          caseSensitive
          aria-label="Value"
          className={cn(
            'justify-start gap-2 font-sans font-normal',
            !selected && 'text-muted-foreground',
            className
          )}
        >
          <CalendarIcon className="size-4 shrink-0" />
          <span className="truncate">
            {selected ? days.format(selected) : 'Pick a day'}
          </span>
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-0">
        <Calendar
          mode="single"
          selected={selected}
          onSelect={(day) => {
            if (!day) {
              onMicros('');

              return;
            }

            const edge = new Date(day);
            const isEnd = operator === 'gt' || operator === 'lte';

            if (isEnd) {
              edge.setHours(23, 59, 59, 999);
            } else {
              edge.setHours(0, 0, 0, 0);
            }

            onMicros(String(edge.getTime() * 1000 + (isEnd ? 999 : 0)));
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

export {
  ACTIVE_GROUP,
  FilterAddMenu,
  FilterConditionSelects,
  FilterSuggestionList,
  FilterValueInput,
  groupTargetProps,
  type TFilterEditorProps,
  type TFilterScope,
  type TFilterSuggestion,
  type TFilterSuggestionRequest,
};

export type TFilterJoin = 'and' | 'or';

/**
 * The operators and variants of a filter field, named as the console's filter
 * vocabulary names them, so that vocabulary is a `TFilterFields` as it is: no
 * adapter between the console's vocabulary and this builder.
 */
export type TFilterOperator =
  | 'eq'
  | 'ne'
  | 'like'
  | 'in'
  | 'isEmpty'
  | 'isNotEmpty'
  | 'lt'
  | 'lte'
  | 'gt'
  | 'gte'
  | 'isBetween'
  | 'dateRange';

export type TFilterVariant =
  | 'text'
  | 'number'
  | 'date'
  | 'dateRange'
  | 'boolean'
  | 'select'
  | 'multiSelect'
  | 'metadata'
  | 'balanceByAsset'
  | 'slider';

export type TFilterOption = { label: string; value: string };

export type TFilterOperatorOption = { label: string; value: TFilterOperator };

/** One field of a resource's filter vocabulary: a `FilterFieldConfig`. */
export type TFilterField = {
  label: string;
  variant: TFilterVariant;
  /** The field's own operators. Without them, the variant's are offered. */
  operators?: readonly TFilterOperatorOption[];
  options?: readonly TFilterOption[];
  placeholder?: string;
  /** For a keyed variant (`metadata`, `balanceByAsset`): the key input. */
  placeholderKey?: string;
  /** For a keyed variant (`metadata`, `balanceByAsset`): the value input. */
  placeholderValue?: string;
  /**
   * For the `metadata` variant: the one key this field is fixed on
   * (`metadata[<key>]`, a key that the field list names). No key is asked.
   */
  key?: string;
  /**
   * For the `metadata` variant: what the consumer knows of each key, by key
   * (the declared type of a ledger's metadata key). A condition on a key
   * listed here offers that key's operators and value input; any other key
   * offers the field's.
   */
  keyTypes?: Readonly<Record<string, TFilterKeyType>>;
};

/** A resource's filter vocabulary, keyed by the path the ledger reads. */
export type TFilterFields = Record<string, TFilterField>;

/**
 * The JSON a key's value is written as: a string, a bool, a number, a decimal
 * string, or a number of signed Unix microseconds (a day, picked as a date).
 */
export type TFilterKeyFormat =
  'string' | 'bool' | 'number' | 'decimalString' | 'unixMicros';

/** One key of a keyed field: the operators it takes, the format of its value. */
export type TFilterKeyType = {
  operators: readonly TFilterOperatorOption[];
  format: TFilterKeyFormat;
};

/**
 * The JSON a metadata value is written as where its text alone does not say
 * it: a JSON bool (a `bool` key's Match) or a decimal string (an unsigned
 * key's bound). Without it, the variant decides: a string to match, a number
 * to bound.
 */
export type TFilterKeyedFormat = 'bool' | 'decimalString';

/**
 * What a condition compares its field with. The same four shapes as the
 * console's `TClauseValue`, so a condition maps onto one of its clauses.
 */
export type TFilterValue =
  /** One value, as text: a number or a boolean is written in the field's type. */
  | { kind: 'text'; text: string }
  /** A list, for `in` on a field that is not keyed. */
  | { kind: 'list'; items: readonly string[] }
  /** A value under a key the reader names: a metadata key, a balance's asset. */
  | {
      kind: 'keyed';
      key: string;
      text: string;
      format?: TFilterKeyedFormat;
      /**
       * The reader types the key: a new condition on the field with no key.
       * A key read from a query, or written by the filter panel, is not
       * typed again: the condition's label names it (`Metadata · <key>`).
       */
      asksKey?: true;
    }
  /** Two instants, both included, for a date range. */
  | { kind: 'instants'; from: string; to: string };

/** One comparison: a field, an operator and a value. */
export type TFilterCondition = {
  kind: 'condition';
  id: string;
  field: string;
  operator: TFilterOperator;
  value: TFilterValue;
};

/** Conditions and groups, joined by one `$and` or one `$or`. */
export type TFilterGroup = {
  kind: 'group';
  id: string;
  join: TFilterJoin;
  children: readonly TFilterNode[];
};

export type TFilterNode = TFilterCondition | TFilterGroup;

/** A ledger query document: `{ $and: [...] }`, `{ $match: { path: value } }`. */
export type TFilterQuery = Record<string, unknown>;

const VARIANT_OPERATORS: Record<TFilterVariant, TFilterOperatorOption[]> = {
  text: [
    { label: 'Match', value: 'eq' },
    { label: 'Is not', value: 'ne' },
    { label: 'Like', value: 'like' },
  ],
  number: [
    { label: 'Match', value: 'eq' },
    { label: 'Lower than', value: 'lt' },
    { label: 'Lower than equal', value: 'lte' },
    { label: 'Greater than', value: 'gt' },
    { label: 'Greater than equal', value: 'gte' },
  ],
  date: [{ label: 'Match', value: 'eq' }],
  dateRange: [{ label: 'Range', value: 'dateRange' }],
  boolean: [
    { label: 'Match', value: 'eq' },
    { label: 'Is not', value: 'ne' },
  ],
  select: [
    { label: 'Match', value: 'eq' },
    { label: 'Is not', value: 'ne' },
  ],
  multiSelect: [
    { label: 'Match', value: 'eq' },
    { label: 'Is not', value: 'ne' },
    { label: 'In', value: 'in' },
  ],
  metadata: [{ label: 'Match', value: 'eq' }],
  balanceByAsset: [
    { label: 'Match', value: 'eq' },
    { label: 'Lower than', value: 'lt' },
    { label: 'Lower than equal', value: 'lte' },
    { label: 'Greater than', value: 'gt' },
    { label: 'Greater than equal', value: 'gte' },
  ],
  slider: [{ label: 'Match', value: 'eq' }],
};

/** Every operator's name, for an operator a field does not list. */
const OPERATOR_LABELS: Record<TFilterOperator, string> = {
  eq: 'Match',
  ne: 'Is not',
  like: 'Like',
  in: 'Is any of',
  isEmpty: 'Is not set',
  isNotEmpty: 'Is set',
  lt: 'Lower than',
  lte: 'Lower than equal',
  gt: 'Greater than',
  gte: 'Greater than equal',
  isBetween: 'Between',
  dateRange: 'Range',
};

/**
 * What the consumer knows of one key of a metadata field, or `null`: a field
 * fixed on a key reads its own key, any other the key it is given.
 */
export function filterKeyType(
  field: TFilterField | undefined,
  key?: string
): TFilterKeyType | null {
  const name = field?.key ?? key?.trim();

  return field?.variant === 'metadata' &&
    field.keyTypes &&
    name !== undefined &&
    Object.hasOwn(field.keyTypes, name)
    ? field.keyTypes[name]!
    : null;
}

/**
 * The operators a field offers: those of its key where the consumer knows the
 * key's type, else the field's own, else its variant's.
 */
export const filterOperators = (
  field: TFilterField,
  key?: string
): readonly TFilterOperatorOption[] =>
  filterKeyType(field, key)?.operators ??
  field.operators ??
  VARIANT_OPERATORS[field.variant];

/**
 * The operators a condition offers: its field's, on its key. An operator the
 * list does not hold stays offered while the condition holds it, so a question
 * read from the raw editor is drawn as it is written and never rewritten. A
 * condition the reader is making (`asksKey`) on a key of a known type is
 * offered that type's operators only.
 */
export function filterConditionOperators(
  condition: TFilterCondition,
  fields: TFilterFields
): readonly TFilterOperatorOption[] {
  const field = fields[condition.field];

  if (!field) {
    return [];
  }

  const { value } = condition;
  const key = value.kind === 'keyed' ? value.key : undefined;
  const operators = filterOperators(field, key);
  const isTypedDraft =
    value.kind === 'keyed' &&
    value.asksKey === true &&
    filterKeyType(field, key) !== null;

  return isTypedDraft ||
    operators.some((one) => one.value === condition.operator)
    ? operators
    : [
        ...operators,
        {
          label:
            field.operators?.find((one) => one.value === condition.operator)
              ?.label ?? OPERATOR_LABELS[condition.operator],
          value: condition.operator,
        },
      ];
}

/**
 * The name a condition's field reads as: its label, and on the metadata field
 * with no key, the key once it is set (`Metadata · <key>`). A key the reader is
 * still typing is in its own input.
 */
export function filterConditionLabel(
  condition: TFilterCondition,
  fields: TFilterFields
): string | null {
  const field = fields[condition.field];
  const { value } = condition;

  if (!field) {
    return null;
  }

  return field.variant === 'metadata' &&
    field.key === undefined &&
    value.kind === 'keyed' &&
    !value.asksKey &&
    value.key.trim() !== ''
    ? `${field.label} · ${value.key.trim()}`
    : field.label;
}

const isKeyedVariant = (variant: TFilterVariant | undefined) =>
  variant === 'metadata' || variant === 'balanceByAsset';

/** The operators that compare nothing: they take no value. */
const takesNoValue = (operator: TFilterOperator) =>
  operator === 'isEmpty' || operator === 'isNotEmpty';

const isBound = (operator: TFilterOperator) =>
  operator === 'lt' ||
  operator === 'lte' ||
  operator === 'gt' ||
  operator === 'gte';

/**
 * The empty value an operator takes on a field. A value of the right shape
 * already typed is kept, so changing `eq` to `ne` does not clear it.
 */
export function filterValueFor(
  field: TFilterField | undefined,
  operator: TFilterOperator,
  current?: TFilterValue
): TFilterValue {
  const kind: TFilterValue['kind'] =
    field?.variant === 'dateRange'
      ? 'instants'
      : isKeyedVariant(field?.variant)
        ? 'keyed'
        : operator === 'in'
          ? 'list'
          : 'text';

  if (current?.kind === kind) {
    return current;
  }

  switch (kind) {
    case 'instants':
      return { kind, from: '', to: '' };
    case 'keyed':
      return field?.variant === 'metadata' && field.key === undefined
        ? { kind, key: '', text: '', asksKey: true }
        : { kind, key: field?.key ?? '', text: '' };
    case 'list':
      return { kind, items: [] };
    case 'text':
      return { kind, text: '' };
  }
}

/**
 * A condition with a value the reader changed. On a key whose type the
 * consumer knows, the operator is one the key takes (its first, where the one
 * held is not), and the value is written in the key's format: a JSON bool, or
 * an unsigned key's bound as a decimal string.
 */
export function withFilterValue(
  condition: TFilterCondition,
  value: TFilterValue,
  fields: TFilterFields
): TFilterCondition {
  const type =
    value.kind === 'keyed'
      ? filterKeyType(fields[condition.field], value.key)
      : null;

  if (!type || value.kind !== 'keyed') {
    return { ...condition, value };
  }

  const operator = type.operators.some(
    ({ value: one }) => one === condition.operator
  )
    ? condition.operator
    : (type.operators[0]?.value ?? condition.operator);
  const format: TFilterKeyedFormat | null =
    type.format === 'bool'
      ? 'bool'
      : type.format === 'decimalString' && isBound(operator)
        ? 'decimalString'
        : null;

  return {
    ...condition,
    operator,
    value: {
      kind: 'keyed',
      key: value.key,
      text: value.text,
      ...(value.asksKey && { asksKey: true }),
      ...(format && { format }),
    },
  };
}

/**
 * The tree with each condition the reader is making (`asksKey`) moved onto
 * its key's type, for a type that arrived after the key was typed: an
 * operator the key takes, a value in its format. A condition read from a
 * query is never rewritten. A tree with nothing to move is returned as it is.
 */
export function withFilterKeyTypes(
  group: TFilterGroup,
  fields: TFilterFields
): TFilterGroup {
  const children = group.children.map((node): TFilterNode => {
    if (node.kind === 'group') {
      return withFilterKeyTypes(node, fields);
    }

    const { value } = node;

    if (
      value.kind !== 'keyed' ||
      value.asksKey !== true ||
      !filterKeyType(fields[node.field], value.key)
    ) {
      return node;
    }

    const typed = withFilterValue(node, value, fields);

    return typed.operator === node.operator &&
      typed.value.kind === 'keyed' &&
      typed.value.format === value.format
      ? node
      : typed;
  });

  return children.every((child, index) => child === group.children[index])
    ? group
    : { ...group, children };
}

/** An id unique in this document, for React keys and drag and drop. */
export const filterNodeId = (): string =>
  `filter-${Math.random().toString(36).slice(2, 10)}`;

/** A new condition on a field: its first operator, an empty value. */
export function createFilterCondition(
  fields: TFilterFields,
  field: string = Object.keys(fields)[0] ?? ''
): TFilterCondition {
  const config = fields[field];
  const operator = config ? (filterOperators(config)[0]?.value ?? 'eq') : 'eq';
  const value = filterValueFor(config, operator);

  return withFilterValue(
    { kind: 'condition', id: filterNodeId(), field, operator, value },
    value,
    fields
  );
}

export const createFilterGroup = (
  join: TFilterJoin = 'and',
  children: readonly TFilterNode[] = []
): TFilterGroup => ({ kind: 'group', id: filterNodeId(), join, children });

/**
 * A new group to open under a group of `parentJoin`: the other join, with one
 * condition. Under an `$or`, the group a reader opens is almost always an
 * `$and`, and the reverse.
 */
export const createFilterSubgroup = (
  fields: TFilterFields,
  parentJoin: TFilterJoin
): TFilterGroup =>
  createFilterGroup(parentJoin === 'and' ? 'or' : 'and', [
    createFilterCondition(fields),
  ]);

/** The conditions a node holds, at any depth. */
export const countFilterConditions = (node: TFilterNode): number =>
  node.kind === 'condition'
    ? 1
    : node.children.reduce(
        (total, child) => total + countFilterConditions(child),
        0
      );

/** The group of this id at any depth, the root included, or `null`. */
export function findFilterGroup(
  node: TFilterNode,
  id: string
): TFilterGroup | null {
  if (node.kind === 'condition') {
    return null;
  }

  if (node.id === id) {
    return node;
  }

  for (const child of node.children) {
    const found = findFilterGroup(child, id);

    if (found) {
      return found;
    }
  }

  return null;
}

/**
 * The tree with the group of this id replaced by `update(group)`, at any
 * depth. A tree without that group is returned as it is.
 */
export function updateFilterGroup(
  root: TFilterGroup,
  id: string,
  update: (group: TFilterGroup) => TFilterGroup
): TFilterGroup {
  if (root.id === id) {
    return update(root);
  }

  return {
    ...root,
    children: root.children.map((child) =>
      child.kind === 'group' ? updateFilterGroup(child, id, update) : child
    ),
  };
}

/** The path the ledger reads: `metadata[type]`, `balance[USD/2]`, `reference`. */
function conditionPath(
  condition: TFilterCondition,
  field: TFilterField | undefined
): string {
  if (condition.value.kind !== 'keyed') {
    return condition.field;
  }

  return field?.variant === 'balanceByAsset'
    ? `balance[${condition.value.key}]`
    : `metadata[${condition.value.key}]`;
}

/**
 * A number as the JSON the ledger reads. An integer past
 * `Number.MAX_SAFE_INTEGER` stays a decimal string: ledger ids are uint64, and
 * `Number()` would round it onto another id.
 */
function toNumber(raw: string): unknown {
  const parsed = Number(raw);

  if (raw.trim() === '' || !Number.isFinite(parsed)) {
    return raw;
  }

  return Number.isInteger(parsed) && !Number.isSafeInteger(parsed)
    ? raw.trim()
    : parsed;
}

/** One text value written in the field's type, or in its own format. */
function scalarOf(
  text: string,
  field: TFilterField | undefined,
  operator: TFilterOperator,
  format?: TFilterKeyedFormat
): unknown {
  switch (field?.variant) {
    case 'boolean':
      return text === 'true';
    case 'number':
    case 'slider':
    case 'balanceByAsset':
      return toNumber(text);
    case 'metadata':
      return format === 'bool'
        ? text.trim() === 'true'
        : format === 'decimalString'
          ? text.trim()
          : operator === 'eq' || operator === 'ne' || operator === 'in'
            ? text
            : toNumber(text);
    default:
      return text;
  }
}

/**
 * The items of a list as the query holds them: trimmed, blanks dropped. The
 * builder keeps a list as typed, so a trailing comma stays in its input.
 */
const cleanItems = (items: readonly string[]): string[] =>
  items.map((one) => one.trim()).filter((one) => one !== '');

/** Whether a condition says enough to be written: a key, a value. */
export function isFilterConditionComplete(
  condition: TFilterCondition
): boolean {
  const { value } = condition;

  if (value.kind === 'keyed' && value.key.trim() === '') {
    return false;
  }

  if (takesNoValue(condition.operator)) {
    return true;
  }

  switch (value.kind) {
    case 'text':
      return value.text.trim() !== '';
    case 'list':
      return cleanItems(value.items).length > 0;
    case 'keyed':
      return value.text.trim() !== '';
    case 'instants':
      return value.from !== '' && value.to !== '';
  }
}

/**
 * The document one condition is written as: the ledger query a flat filter
 * writes for the same field, operator and value, so the ledger reads it as it
 * reads the flat filters. A date range is one `$and` of a `$gte` and a `$lte`,
 * which the ledger reads as one range.
 */
function conditionQuery(
  condition: TFilterCondition,
  fields: TFilterFields
): TFilterQuery | null {
  if (!isFilterConditionComplete(condition)) {
    return null;
  }

  const field = fields[condition.field];
  const path = conditionPath(condition, field);
  const { operator, value } = condition;

  if (value.kind === 'instants') {
    return {
      $and: [{ $gte: { [path]: value.from } }, { $lte: { [path]: value.to } }],
    };
  }

  if (takesNoValue(operator)) {
    // The ledger reads a metadata key's presence as `{"$exists": {"metadata":
    // "<key>"}}` and refuses `metadata[<key>]` as the field of an `$exists`.
    const exists = {
      $exists:
        value.kind === 'keyed' && field?.variant === 'metadata'
          ? { metadata: value.key }
          : { [path]: true },
    };

    return operator === 'isEmpty' ? { $not: exists } : exists;
  }

  if (value.kind === 'list') {
    return { $in: { [path]: cleanItems(value.items) } };
  }

  if (operator === 'in') {
    // A keyed "in" is typed comma-separated.
    const items = cleanItems(value.text.split(','));

    return items.length === 1
      ? { $match: { [path]: items[0] } }
      : { $or: items.map((one) => ({ $match: { [path]: one } })) };
  }

  const scalar = scalarOf(
    value.text,
    field,
    operator,
    value.kind === 'keyed' ? value.format : undefined
  );

  switch (operator) {
    case 'ne':
      return { $not: { $match: { [path]: scalar } } };
    case 'like':
      return { $like: { [path]: scalar } };
    case 'lt':
    case 'lte':
    case 'gt':
    case 'gte':
      return { [`$${operator}`]: { [path]: scalar } };
    default:
      return { $match: { [path]: scalar } };
  }
}

/**
 * The ledger query a filter asks. A group is one `$and` or `$or` of its
 * children; a group that holds one written child is that child; a condition
 * that is not complete is left out. Nothing written is `null`: every row.
 */
export function queryOfFilter(
  node: TFilterNode,
  fields: TFilterFields
): TFilterQuery | null {
  if (node.kind === 'condition') {
    return conditionQuery(node, fields);
  }

  const parts = node.children
    .map((child) => queryOfFilter(child, fields))
    .filter((part): part is TFilterQuery => part !== null);

  if (parts.length === 0) {
    return null;
  }

  return parts.length === 1 ? parts[0]! : { [`$${node.join}`]: parts };
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

/** The one key of an object that holds exactly one, or `null`. */
function onlyKey(value: unknown): string | null {
  if (!isRecord(value)) {
    return null;
  }

  const keys = Object.keys(value);

  return keys.length === 1 ? keys[0]! : null;
}

/**
 * The field and named key a ledger path is read under. A metadata key with a
 * field of its own (`key`) is read on that field, any other key on the keyed
 * field with no key.
 */
function fieldOfPath(
  path: string,
  fields: TFilterFields
): { field: string; key: string | null } | null {
  const keyed = /^(metadata|balance)\[(.+)\]$/.exec(path);

  if (keyed) {
    const variant = keyed[1] === 'metadata' ? 'metadata' : 'balanceByAsset';
    const key = keyed[2]!;
    const ids = Object.keys(fields).filter(
      (one) => fields[one]?.variant === variant
    );
    const field =
      ids.find((one) => fields[one]?.key === key) ??
      ids.find((one) => fields[one]?.key === undefined);

    return field ? { field, key } : null;
  }

  return fields[path] && !isKeyedVariant(fields[path].variant)
    ? { field: path, key: null }
    : null;
}

const LEAF_OPERATORS: Record<string, TFilterOperator> = {
  $match: 'eq',
  $like: 'like',
  $in: 'in',
  $lt: 'lt',
  $lte: 'lte',
  $gt: 'gt',
  $gte: 'gte',
  $exists: 'isNotEmpty',
};

/** One comparison on one path, `{ $op: { path: raw } }`, or its `$not`. */
function leafOf(
  part: unknown
): { operator: TFilterOperator; path: string; raw: unknown } | null {
  const op = onlyKey(part);

  if (op === null || !isRecord(part)) {
    return null;
  }

  if (op === '$not') {
    const inner = leafOf(part.$not);
    const negated =
      inner?.operator === 'eq'
        ? 'ne'
        : inner?.operator === 'isNotEmpty'
          ? 'isEmpty'
          : null;

    return inner && negated ? { ...inner, operator: negated } : null;
  }

  const operator = LEAF_OPERATORS[op];
  const body = part[op];
  const path = onlyKey(body);

  if (!operator || path === null || !isRecord(body)) {
    return null;
  }

  // `{"$exists": {"metadata": "<key>"}}`: the presence of one metadata key.
  return op === '$exists' &&
    path === 'metadata' &&
    typeof body[path] === 'string'
    ? { operator, path: `metadata[${body[path]}]`, raw: '' }
    : { operator, path, raw: body[path] };
}

const textOf = (raw: unknown): string | null =>
  typeof raw === 'string' || typeof raw === 'number' || typeof raw === 'boolean'
    ? String(raw)
    : null;

/** A date range: an `$and` of a `$gte` then a `$lte` on one range field. */
function rangeOf(part: unknown, fields: TFilterFields): TFilterNode | null {
  const members = isRecord(part) ? part.$and : null;

  if (!Array.isArray(members) || members.length !== 2) {
    return null;
  }

  const from = leafOf(members[0]);
  const to = leafOf(members[1]);
  const fromText = textOf(from?.raw);
  const toText = textOf(to?.raw);

  if (
    from?.operator !== 'gte' ||
    to?.operator !== 'lte' ||
    from.path !== to.path ||
    fields[from.path]?.variant !== 'dateRange' ||
    fromText === null ||
    toText === null
  ) {
    return null;
  }

  return {
    kind: 'condition',
    id: filterNodeId(),
    field: from.path,
    operator: 'dateRange',
    value: { kind: 'instants', from: fromText, to: toText },
  };
}

/** The node one part of a query is, or `null` for a shape it cannot hold. */
function nodeOf(part: unknown, fields: TFilterFields): TFilterNode | null {
  const range = rangeOf(part, fields);

  if (range) {
    return range;
  }

  const op = onlyKey(part);

  if ((op === '$and' || op === '$or') && isRecord(part)) {
    const members = part[op];

    if (!Array.isArray(members)) {
      return null;
    }

    const children = members.map((member) => nodeOf(member, fields));

    return children.every((child): child is TFilterNode => child !== null)
      ? createFilterGroup(op === '$and' ? 'and' : 'or', children)
      : null;
  }

  const leaf = leafOf(part);
  const target = leaf ? fieldOfPath(leaf.path, fields) : null;

  if (!leaf || !target) {
    return null;
  }

  const items = Array.isArray(leaf.raw) ? leaf.raw.map(textOf) : null;
  const text = textOf(leaf.raw);
  // A metadata value the text alone would write as another JSON: a bool, or
  // a bound written as a decimal string (an unsigned key's).
  const format: TFilterKeyedFormat | null =
    fields[target.field]?.variant !== 'metadata'
      ? null
      : typeof leaf.raw === 'boolean'
        ? 'bool'
        : typeof leaf.raw === 'string' &&
            isBound(leaf.operator) &&
            /^\d+$/.test(leaf.raw)
          ? 'decimalString'
          : null;
  const value: TFilterValue | null =
    target.key !== null
      ? text === null
        ? null
        : {
            kind: 'keyed',
            key: target.key,
            text,
            ...(format && { format }),
          }
      : items
        ? items.every((one): one is string => one !== null)
          ? { kind: 'list', items }
          : null
        : text === null
          ? null
          : { kind: 'text', text };

  return value
    ? {
        kind: 'condition',
        id: filterNodeId(),
        field: target.field,
        operator: leaf.operator,
        value: !takesNoValue(leaf.operator)
          ? value
          : value.kind === 'keyed'
            ? { ...value, text: '' }
            : filterValueFor(fields[target.field], leaf.operator),
      }
    : null;
}

/**
 * The filter a stored ledger query is drawn as, or `null` when the builder
 * cannot hold it exactly.
 *
 * **Reading never loses anything**: the filter read is
 * written back and compared with the query, so a query a colleague sent is
 * never rewritten by the screen that shows it. A `null` is the caller's cue to
 * open the raw editor instead. The root is always a group, so a lone `$match`
 * is a group of one condition.
 */
export function filterOfQuery(
  query: TFilterQuery | null,
  fields: TFilterFields
): TFilterGroup | null {
  if (query === null || Object.keys(query).length === 0) {
    return createFilterGroup();
  }

  const node = nodeOf(query, fields);

  if (!node) {
    return null;
  }

  const root = node.kind === 'group' ? node : createFilterGroup('and', [node]);

  return JSON.stringify(queryOfFilter(root, fields)) === JSON.stringify(query)
    ? root
    : null;
}

/** A SQL `LIKE` pattern as a whole-value regular expression. */
const likePattern = (pattern: string): RegExp =>
  new RegExp(
    `^${pattern
      .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      .replace(/%/g, '.*')
      .replace(/_/g, '.')}$`,
    'i'
  );

/** A row value or a written threshold as decimal text, or `null` if no number. */
const decimalOf = (one: unknown): string | null => {
  if (typeof one === 'number') {
    return Number.isFinite(one) ? String(one) : null;
  }

  return typeof one === 'string' &&
    one.trim() !== '' &&
    Number.isFinite(Number(one))
    ? one.trim()
    : null;
};

const INTEGER = /^-?\d+$/;

/**
 * The sign of `actual - expected`, or `null` when one of them is no number.
 * Two integers compare as `BigInt`: a uint64 id past `Number.MAX_SAFE_INTEGER`
 * stays a decimal string in the query, and `Number()` would round it onto a
 * neighbour.
 */
function compareNumbers(actual: unknown, expected: unknown): number | null {
  const left = decimalOf(actual);
  const right = decimalOf(expected);

  if (left === null || right === null) {
    return null;
  }

  if (INTEGER.test(left) && INTEGER.test(right)) {
    const [a, b] = [BigInt(left), BigInt(right)];

    return a === b ? 0 : a < b ? -1 : 1;
  }

  return Math.sign(Number(left) - Number(right));
}

/** Whether one row passes one complete condition. */
function conditionMatches(
  condition: TFilterCondition,
  fields: TFilterFields,
  read: (path: string) => unknown
): boolean {
  const field = fields[condition.field];
  const actual = read(conditionPath(condition, field));
  const { operator, value } = condition;
  const empty = actual === undefined || actual === null || actual === '';

  if (operator === 'isEmpty') {
    return empty;
  }

  if (operator === 'isNotEmpty') {
    return !empty;
  }

  if (value.kind === 'instants') {
    const at = new Date(String(actual)).getTime();

    return (
      at >= new Date(value.from).getTime() && at <= new Date(value.to).getTime()
    );
  }

  if (value.kind === 'list') {
    return cleanItems(value.items).includes(String(actual));
  }

  const text = value.text;

  if (operator === 'in') {
    return cleanItems(text.split(',')).includes(String(actual));
  }

  const expected = scalarOf(
    text,
    field,
    operator,
    value.kind === 'keyed' ? value.format : undefined
  );
  const compare = compareNumbers(actual, expected);

  switch (operator) {
    case 'ne':
      return String(actual) !== String(expected);
    case 'like':
      return likePattern(text).test(String(actual));
    case 'lt':
      return compare !== null && compare < 0;
    case 'lte':
      return compare !== null && compare <= 0;
    case 'gt':
      return compare !== null && compare > 0;
    case 'gte':
      return compare !== null && compare >= 0;
    default:
      return String(actual) === String(expected);
  }
}

/**
 * Whether one row passes the written part of a node, or `null` when nothing
 * in it is written. A condition that is not complete is left out, as it is
 * left out of the query: under an `$or`, it must not let every row through.
 */
function writtenMatches(
  node: TFilterNode,
  fields: TFilterFields,
  read: (path: string) => unknown
): boolean | null {
  if (node.kind === 'condition') {
    return isFilterConditionComplete(node)
      ? conditionMatches(node, fields, read)
      : null;
  }

  const results = node.children
    .map((child) => writtenMatches(child, fields, read))
    .filter((result) => result !== null);

  if (results.length === 0) {
    return null;
  }

  return node.join === 'and'
    ? results.every((result) => result)
    : results.some((result) => result);
}

/**
 * Whether one row passes a filter, for a table filtered in the browser. `read`
 * gives the row's value at a ledger path (`metadata[type]`, `reference`). A
 * filter with nothing written lets every row through.
 */
export const filterMatches = (
  node: TFilterNode,
  fields: TFilterFields,
  read: (path: string) => unknown
): boolean => writtenMatches(node, fields, read) ?? true;
